#!/usr/bin/env node
/* gate1-golden-mirror.cjs — EVIDENCE lane (92dc40cb) independent ethers mirror for gate-1 (M2).
 *
 * Reproduces the ESCROW lane's published golden vectors (~/.claude/shared/vnext-golden-vectors-v1.md,
 * generated by the Solidity VNextSettlementLib `test_emit_goldenVectors`) from an INDEPENDENT ethers
 * implementation, over the SAME canonical inputs, and asserts BYTE-EXACT + field-mutation rejection.
 * A JS(ethers) result identical to the Solidity result is the cross-implementation M2 proof.
 *
 * Run (ethers resolved from a sibling repo — no dep added to this repo):
 *   NODE_PATH=/c/Users/globa/pcc-oracle/node_modules node gate1-golden-mirror.cjs
 */
const E = require('ethers');
const keccak256 = E.keccak256 || E.utils.keccak256;
const toUtf8Bytes = E.toUtf8Bytes || E.utils.toUtf8Bytes;
const coder = E.AbiCoder ? E.AbiCoder.defaultAbiCoder() : E.utils.defaultAbiCoder;
const enc = (t, v) => coder.encode(t, v);
const K = (s) => keccak256(toUtf8Bytes(s)); // Solidity keccak256("literal") == keccak of its utf8 bytes
const addr = (n) => '0x' + n.toString(16).padStart(40, '0');
const Z32 = '0x' + '0'.repeat(64);

// ── canonical inputs (EXACT, from VNextSettlementEscrow.t.sol :: test_emit_goldenVectors) ──
const chainId = 8453n; // Base mainnet
const escrow = addr(0xe5c0fn); // address(0xE5C0F)
const feeRecipient = addr(0xfee0n); // address(0xFEE0)
const jobIdHash = K('golden-job');
const stepId = K('golden-step');
const bundleHash = K('golden-bundle');
const verdictHash = K('golden-verdict');
const mi = 3n;
const feeBps = 235n;
const SUD = K('PCC:vnext:settlement-unit:v1');

// ── independent derivations (frozen §2 / #382 / #393 forms; ABI-standard abi.encode) ──
const unitId = keccak256(enc(
  ['bytes32', 'uint256', 'address', 'bytes32', 'uint256', 'bytes32'],
  [SUD, chainId, escrow, jobIdHash, mi, stepId]));

const feeSchedTypes = ['uint8', 'uint256', 'address', 'bytes32', 'uint8', 'uint256', 'uint256',
  'uint256', 'uint16', 'uint256', 'uint8', 'address', 'bytes32'];
const feeScheduleHash = keccak256(enc(feeSchedTypes,
  [1n, chainId, escrow, unitId, 0n, 1000000n, 23500n, 976500n, feeBps, 10000n, 0n, feeRecipient, Z32]));

const payoutConfigHash = keccak256(enc(
  ['bytes32', 'tuple(address,uint256)[]'],
  [unitId, [[addr(0xaaa1n), 500000n], [addr(0xbbb2n), 476500n]]]));

const claimId = (leg, cls) => keccak256(enc(
  ['uint256', 'address', 'bytes32', 'uint256', 'uint8'], [chainId, escrow, unitId, leg, cls]));
const claimPrincipal = claimId(0n, 0n); // PRINCIPAL=0, legIndex 0
const claimFee = claimId((1n << 256n) - 1n, 1n); // FEE=1, legIndex 2^256-1

// O5Verdict: Solidity `abi.encode(v)` over an all-STATIC 14-field struct == abi.encode(the 14 fields).
// v1.1/rev-3 (escrow #453): field13 uint64 oracleAuthEpoch + field14 bytes32 compositionRoot appended
// AFTER settlementUnitId (the 12 originals unchanged, same order). abi.encode length 384 -> 448.
const oracleAuthEpoch = 7n;                            // golden sample (escrow #453)
const compositionRoot = K('golden-composition-root');  // golden sample; typed H(SCHEMA_ID,root) is composition-owned — mirror echoes the frozen bytes32
const o5Types = ['bytes32', 'uint256', 'bytes32', 'bytes32', 'uint8', 'uint8', 'uint8', 'bytes32',
  'uint16', 'address', 'bytes32', 'bytes32', 'uint64', 'bytes32'];
const o5vals = [jobIdHash, mi, stepId, bundleHash, 2n, 2n, 1n, verdictHash, feeBps, feeRecipient, feeScheduleHash, unitId,
  oracleAuthEpoch, compositionRoot];
const o5enc = enc(o5Types, o5vals);
const o5len = (o5enc.length - 2) / 2;
const o5keccak = keccak256(o5enc);

// ── escrow-published expected outputs (vnext-golden-vectors-v1.md) ──
const expected = {
  settlementUnitId: '0x4453a3d232c24342539bc5ae06089f1cf7ccf93f737cffd67cf0a6ea76904ef1',
  feeScheduleHash: '0xa7646da5acf16488d3c5440124cc592e3c2a093415bcb822016b90f60093f8ee',
  payoutConfigHash: '0x021b0725269574dabdce218dcc0ad26b792e1a7ab0208e8cbc52a75a1247bcaf',
  claimId_PRINCIPAL_leg0: '0x3995df0c1f8efea68e2b9f7ff59ef7274cc93fd3de62db59bd876a32d20fdc3f',
  claimId_FEE: '0x49b29be7b292412e367b10683c6f2cc17f1201794d2ca22783ce65abf0437be7',
  o5Verdict_keccak: '0x8f3ae745b77d9ea76f472abb7b34de68fdf8365c652b1013913c5d444899edf7',
};
const got = {
  settlementUnitId: unitId,
  feeScheduleHash,
  payoutConfigHash,
  claimId_PRINCIPAL_leg0: claimPrincipal,
  claimId_FEE: claimFee,
  o5Verdict_keccak: o5keccak,
};

console.log(`ethers=${E.version || 'v5.x'}  (independent of the Solidity contract)\n`);
let ok = true;
for (const k of Object.keys(expected)) {
  const pass = got[k].toLowerCase() === expected[k].toLowerCase();
  ok = ok && pass;
  console.log(`${pass ? 'PASS' : 'FAIL'}  ${k}\n        got  ${got[k]}` + (pass ? '' : `\n        want ${expected[k]}`));
}
const lenOk = o5len === 448;
ok = ok && lenOk;
console.log(`${lenOk ? 'PASS' : 'FAIL'}  o5Verdict_encoded_length = ${o5len} bytes (expected 448)`);

// field-mutation rejection: a single-field change MUST change the hash
const mutFee = keccak256(enc(feeSchedTypes,
  [1n, chainId, escrow, unitId, 0n, 1000000n, 23500n, 976500n, 236n, 10000n, 0n, feeRecipient, Z32]));
const mutOk = mutFee.toLowerCase() !== feeScheduleHash.toLowerCase();
ok = ok && mutOk;
console.log(`${mutOk ? 'PASS' : 'FAIL'}  field-mutation rejection (feeBps 235->236 changes feeScheduleHash)`);

// O5 field-mutation: the two NEW appended words must BIND into the keccak (not be silently ignored)
const mutEpoch = keccak256(enc(o5Types, [...o5vals.slice(0, 12), 8n, compositionRoot])); // oracleAuthEpoch 7->8
const epochOk = mutEpoch.toLowerCase() !== o5keccak.toLowerCase();
ok = ok && epochOk;
console.log(`${epochOk ? 'PASS' : 'FAIL'}  O5 field-mutation: oracleAuthEpoch 7->8 changes o5Verdict keccak`);
const mutRoot = keccak256(enc(o5Types, [...o5vals.slice(0, 13), Z32])); // compositionRoot -> 0 (non-composed)
const rootOk = mutRoot.toLowerCase() !== o5keccak.toLowerCase();
ok = ok && rootOk;
console.log(`${rootOk ? 'PASS' : 'FAIL'}  O5 field-mutation: compositionRoot nonzero vs 0 (non-composed) changes o5Verdict keccak`);

console.log(`\n${ok ? 'GATE-1 EVIDENCE MIRROR: ALL BYTE-EXACT vs escrow golden vectors OK' : 'GATE-1 EVIDENCE MIRROR: DIVERGENCE -- pre-deploy blocker'}`);
process.exit(ok ? 0 : 1);
